'use strict';class ModalTemplates{static AlbumCommentsModalHead({metadata:a}){return`
        <div class="modal fade" id="propalbumphotocomment${a.id}" tabindex="-1" role="dialog" aria-labelledby="label${a.id}" aria-hidden="true">
            <div class="modal-dialog modal-lg modal-dialog-scrollable" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title" id="commentModalLabel">
                            <div id="propalbumphotocomment${a.id}">
                                <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" width="100" height="100">
                            </div>Comments for ${a.fileName}
                        </h5>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                    </div>
                    <div class="modal-body">
                        <input type="hidden" id="currentCommentId${a.id}" name="currentCommentId${a.id}">
                        <ul class="list-group" id="commentList${a.id}">
    `}static AlbumComment({commentId:a,commentText:b,userId:c,commentUserId:d,username:e}){return`
        <li class="list-group-item${d===c?" list-group-item-secondary":""}" id="comment${a}">
            <span id="commentcontainer${a}">
                <p id="commentcontent${a}">${b}</p>
                ${d===c?`<small>${e}<span style="float: right"><a href="#" id="deletecomment${a}"><span class="bi-trash"></span></a>&nbsp;&nbsp;<a href="#" id="editcomment${a}"><span class="bi-pencil"></span></a></span></small>`:""}
            </span>
            <span id="textareacontainer${a}"></span>
        </li>
    `}static AlbumCommentsModalFooter({metadata:a}){return`
                        </ul>
                    </div>
                    <div class="modal-footer">
                        <textarea class="form-control" id="commentText${a.id}" rows="2"></textarea>
                        <button type="button" class="btn btn-primary" id="saveCommentMetadata${a.id}">Save</button>
                        <button type="button" class="btn btn-primary" id="updateCommentMetadata${a.id}">Update</button>
                        <button type="button" class="btn btn-secondary" id="dismissModalCommentMetadata${a.id}" data-bs-dismiss="modal">Close</button>
                        <button type="button" class="btn btn-secondary" id="cancelEditCommentMetadata${a.id}">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    `}static AlbumModalDropdownHeader({metadata:a}){return`
        <div class="input-group-append dropdown" id="albumListInput">
            <button class="btn btn-outline-secondary dropdown-toggle" id="albumdropdown${a.id}" type="button" aria-haspopup="true" aria-expanded="false">Albums</button>
            <div class="dropdown-menu" id="albumsList">
    `}static AlbumModalDropDown({metadata:a,album:b,checkedString:c}){return`
                <button class="dropdown-item" type="button">
                    <input type="checkbox" class="album" value="${b.name}" name="album${a.id}[]" id="${a.id}-${b.id}"${c}>
                    <label for="${a.id}-${b.id}" id="album-${a.id}-${b.id}">${Util.escapeHtml(b.name)}</label>
                </button>
    `}static AlbumModalDropdownFooter(){return"\n            </div>\n        </div>\n    "}static PersonModalHead({module:a,metadata:b,recognitionLabels:c,taggedPeopleList:d}){return`
        <div class="modal fade" id="prop${a}${b.id}" tabindex="-1" role="dialog" aria-labelledby="label${b.id}" aria-hidden="true">
            <div class="modal-dialog modal-dialog-scrollable modal-lg" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title" id="exampleModalLabel">Edit "${b.title}"
                            <div id="prop${a}Thumbnail${b.id}">
                                <img loading="lazy" src="${encodeURI(b.thumbnailUrlCentered)}" width="100" height="100">
                            </div>
                        </h5>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                    </div>
                    <div class="modal-body">
                        <form th:id="saveData${b.id}">
                            <input type="hidden" name="id" value="${b.id}">
                            <div class="form-group row">
                                <div class="col-sm">
                                    <label for="tagpeople${b.id}" class="col-form-label">Tag People (comma separated)</label>
                                    <div class="input-group" id="batchLabelIds${b.id}">
                                        <input type="text" class="form-control" aria-label="Tag People" id="tagpeople${b.id}" name="tagpeople" value="${d}">
                                        ${0<c.length?`
                                        <div class="input-group-append">
                                            <button class="btn btn-outline-secondary dropdown-toggle" id="tagpeopledropdown${b.id}" type="button" aria-haspopup="true" aria-expanded="false">People</button>
                                            <div class="dropdown-menu ${a}Dropdown" id="recognitionLabelsList${b.id}">
                                        `:""}
    `}static PersonModalDropdownHead({metadata:a}){return`
        <div class="input-group-append dropdown" id="recognitionLabelInput">
            <button class="btn btn-outline-secondary dropdown-toggle" id="tagpeopledropdown${a.id}" type="button" aria-haspopup="true" aria-expanded="false">People</button>
            <div class="dropdown-menu" id="recognitionLabelsList">
    `}static PersonModalDropDown({metadata:a,recognitionLabel:b,checkedString:c}){return`
                                                ${null===b.name||"null"===b.name?"":`
                                                <button class="dropdown-item" type="button">
                                                    <input type="checkbox" class="recognitionLabel" value="${b.name}" name="recognitionLabel${a.id}[]" id="${0<a.id.length?`${a.id}-`:""}${b.id}"${0<c.length?`${c}`:""}>
                                                    <label for="${0<a.id.length?`${a.id}-`:""}${b.id}" id="label${0<a.id.length?`-${a.id}-`:""}${b.id}">${b.name}</label>
                                                </button>`}
    `}static PersonModalDropdownFooter(){return"\n            </div>\n        </div>\n    "}static PersonModalFooter({module:a,metadata:b,recognitionLabels:c}){return`
                                        ${0<c.length?"\n                                            </div>\n                                        </div>\n                                        ":""}
                                    </div>
                                </div>
                            </div>
                            <div class="form-group row">
                                <div class="col-sm">
                                    <input type="checkbox" name="isobject${b.id}" id="isobject${b.id}">
                                    <label class="form-check-label" for="isobject${b.id}">This is not a person</label>
                                </div>
                            </div>
                        </form>
                        <div class="col-sm">
                            <span id="msg${b.id}"></span>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <div id="${a}ModalStatus${b.id}" class="spinner-grow me-auto" style="visibility: hidden;font-size: 2rem;" role="status" aria-hidden="true" data-bs-toggle="tooltip" data-bs-placement="right" title=""></div>
                        <button type="button" class="btn btn-primary" id="saveMetadata${b.id}">Save</button>
                        <button id="${a}ModalCancel${b.id}" type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    `}}
;
